-- ============================================================
-- 20261015000001 - CORE: helpers + tables
-- ============================================================
-- Design rules (why inserts no longer fail):
--   * Every NOT NULL column that the app does not send has either a
--     DEFAULT or is filled by a BEFORE INSERT trigger (see ..0002).
--   * IDs are "generated BY DEFAULT" so imports / restores that carry
--     their own ids work (call public.fix_sequences() afterwards).
--   * No extensions are required (no citext / pg_trgm / pgcrypto), so
--     nothing can fail on a project that restricts extensions.
--   * Money is numeric(12,2) everywhere.
--   * Foreign keys use RESTRICT for business records and SET NULL for
--     "who did it" columns, so removing a login never breaks history.
-- ============================================================

-- Business timezone. Supabase runs in UTC; the business is in Asia/Karachi.
create or replace function public.today_pk()
returns date language sql stable
as $$ select (now() at time zone 'Asia/Karachi')::date $$;

-- ------------------------------------------------------------
-- PROFILES - application logins, 1:1 with auth.users
-- ------------------------------------------------------------
create table public.profiles (
  id          uuid primary key references auth.users(id) on delete cascade,
  full_name   text not null check (btrim(full_name) <> ''),
  role        text not null default 'staff' check (role in ('admin','staff')),
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- ------------------------------------------------------------
-- AREAS - villages / zones served
-- ------------------------------------------------------------
create table public.areas (
  id          bigint generated by default as identity primary key,
  name        text not null check (btrim(name) <> ''),
  description text,
  created_at  timestamptz not null default now()
);
create unique index areas_name_uniq on public.areas (lower(btrim(name)));

-- ------------------------------------------------------------
-- PACKAGES - billing tiers
-- ------------------------------------------------------------
create table public.packages (
  id           bigint generated by default as identity primary key,
  name         text not null check (btrim(name) <> ''),
  speed_label  text,
  monthly_fee  numeric(12,2) not null check (monthly_fee >= 0),
  description  text,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create unique index packages_name_uniq on public.packages (lower(btrim(name)));

-- ------------------------------------------------------------
-- EMPLOYEES - HR record; optionally linked to a login (profile_id)
-- ------------------------------------------------------------
create table public.employees (
  id              bigint generated by default as identity primary key,
  profile_id      uuid unique references public.profiles(id) on delete set null,
  full_name       text not null check (btrim(full_name) <> ''),
  phone           text,
  role_title      text,
  area_id         bigint references public.areas(id) on delete set null,
  monthly_salary  numeric(12,2) check (monthly_salary is null or monthly_salary >= 0),
  is_active       boolean not null default true,
  joined_at       date not null default public.today_pk(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index employees_area_idx   on public.employees (area_id);
create index employees_active_idx on public.employees (is_active);

-- ------------------------------------------------------------
-- CUSTOMERS
--   customer_code : filled by trigger (CUS-00001...) if not supplied
--   opening_balance: dues carried over from the paper register.
--                    May be NEGATIVE (customer paid in advance).
--   balance       : DERIVED, maintained by triggers - never edit by hand
--   join_date     : first month the customer can be billed
-- ------------------------------------------------------------
create table public.customers (
  id               bigint generated by default as identity primary key,
  customer_code    text not null unique,
  username         text not null check (btrim(username) <> ''),
  phone            text not null,
  package_id       bigint not null references public.packages(id) on delete restrict,
  area_id          bigint not null references public.areas(id)    on delete restrict,
  seller_id        bigint references public.employees(id) on delete set null,
  address          text,
  opening_balance  numeric(12,2) not null default 0,
  balance          numeric(12,2) not null default 0,
  service_status   text not null default 'on'     check (service_status  in ('on','off')),
  customer_status  text not null default 'active' check (customer_status in ('active','inactive')),
  cnic             text,
  father_name      text,
  notes            text,
  join_date        date not null default public.today_pk(),
  created_by       uuid references public.profiles(id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index customers_area_idx     on public.customers (area_id);
create index customers_package_idx  on public.customers (package_id);
create index customers_seller_idx   on public.customers (seller_id);
create index customers_status_idx   on public.customers (customer_status);
create index customers_phone_idx    on public.customers (phone);
create index customers_username_idx on public.customers (lower(username));

-- ------------------------------------------------------------
-- MONTHLY_FEES - one fee per customer per month
--   billing_month : any date in the month is accepted; the trigger
--                   normalises it to the 1st
--   due_date      : defaults to the 10th of the month
--   amount_due    : defaults to the package fee; it is a SNAPSHOT
-- ------------------------------------------------------------
create table public.monthly_fees (
  id             bigint generated by default as identity primary key,
  customer_id    bigint not null references public.customers(id) on delete restrict,
  billing_month  date not null,
  amount_due     numeric(12,2) not null check (amount_due >= 0),
  due_date       date not null,
  package_id     bigint references public.packages(id) on delete set null,
  created_by     uuid references public.profiles(id) on delete set null,
  created_at     timestamptz not null default now(),
  constraint monthly_fees_customer_month_uniq unique (customer_id, billing_month),
  constraint monthly_fees_id_customer_uniq    unique (id, customer_id),
  constraint monthly_fees_first_of_month check (billing_month = date_trunc('month', billing_month::timestamp)::date)
);
create index monthly_fees_month_idx on public.monthly_fees (billing_month);
create index monthly_fees_due_idx   on public.monthly_fees (due_date);

-- ------------------------------------------------------------
-- PAYMENTS - never deleted; corrected by reversal
--   customer_id    : filled from the fee; the composite FK guarantees a
--                    payment can never point at another customer's fee
--   receipt_number : generated by trigger (RCP-YYYY-NNNNNN)
--   received_by    : stamped from the logged-in user (null for SQL imports)
-- ------------------------------------------------------------
create table public.payments (
  id                bigint generated by default as identity primary key,
  customer_id       bigint not null references public.customers(id) on delete restrict,
  monthly_fee_id    bigint not null,
  amount_paid       numeric(12,2) not null check (amount_paid > 0),
  payment_method    text not null default 'cash' check (payment_method in ('cash','bank_transfer','other')),
  payment_date      date not null default public.today_pk(),
  received_by       uuid references public.profiles(id) on delete set null,
  receipt_number    text not null unique,
  notes             text,
  reversed_at       timestamptz,
  reversed_by       uuid references public.profiles(id) on delete set null,
  reversal_reason   text,
  whatsapp_sent     boolean not null default false,
  whatsapp_sent_at  timestamptz,
  created_at        timestamptz not null default now(),
  constraint payments_fee_customer_fk
    foreign key (monthly_fee_id, customer_id) references public.monthly_fees (id, customer_id) on delete restrict,
  constraint payments_reversal_consistent
    check (reversed_at is not null or (reversed_by is null and reversal_reason is null))
);
create index payments_customer_idx    on public.payments (customer_id);
create index payments_fee_idx         on public.payments (monthly_fee_id);
create index payments_date_idx        on public.payments (payment_date);
create index payments_received_by_idx on public.payments (received_by);

