-- ============================================================
-- Helper functions (need the tables above)
-- ============================================================

-- Active admin?
create or replace function public.is_admin()
returns boolean language sql security definer stable set search_path = public, auth
as $$ select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin' and is_active) $$;

-- Any active login?
create or replace function public.is_active_user()
returns boolean language sql security definer stable set search_path = public, auth
as $$ select exists (select 1 from public.profiles where id = auth.uid() and is_active) $$;

-- SQL editor / migrations / service role (not a browser session).
create or replace function public.is_trusted_session()
returns boolean language sql stable
as $$ select current_user in ('postgres', 'supabase_admin', 'service_role') $$;

-- Same idea, but for SECURITY DEFINER functions, where current_user is always the
-- function owner. Looks at the original caller instead: no JWT (SQL editor) or the
-- service role is trusted; 'authenticated' / 'anon' browser sessions never are.
create or replace function public.is_trusted_caller()
returns boolean language sql stable
as $$ select coalesce(auth.role(), '') not in ('authenticated', 'anon') $$;

-- True while a bulk import / restore is running:
--   begin; select set_config('app.bulk_load', 'on', true); ...inserts...; commit;
-- It switches OFF the automatic side-effects (journal, account postings,
-- audit rows, auto-created fees) so historical data can be loaded as-is.
create or replace function public.is_bulk_load()
returns boolean language sql stable
as $$ select coalesce(current_setting('app.bulk_load', true), '') = 'on' $$;

create or replace function public.company_name()
returns text language sql immutable
as $$ select 'Rana Cable Internet'::text $$;

-- Phone normaliser. Pakistani mobiles become 03XXXXXXXXX; any other number
-- (landline, foreign) is kept as digits instead of being rejected.
-- Returns NULL only when there are fewer than 7 or more than 15 digits.
create or replace function public.normalize_phone(p text)
returns text language plpgsql immutable
as $$
declare d text := regexp_replace(coalesce(p, ''), '\D', '', 'g');
begin
  if d like '0092%' then d := substr(d, 5);
  elsif d like '92%' and length(d) = 12 then d := substr(d, 3);
  end if;
  if length(d) = 10 and d like '3%' then d := '0' || d; end if;
  if d ~ '^03[0-9]{9}$' then return d; end if;
  if length(d) between 7 and 15 then return d; end if;
  return null;
end $$;

-- >>>>>>>> migrations/20261015000002_logic.sql
-- ============================================================
-- 20261015000002 - LOGIC: triggers and internal functions
-- ============================================================
-- Rule: the database fills in everything the app should not have
-- to send (codes, receipt numbers, due dates, creators, balances),
-- and enforces the money rules even for direct SQL inserts.
-- ============================================================

-- ------------------------------------------------------------
-- updated_at
-- ------------------------------------------------------------
create or replace function public.tg_set_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;

create trigger trg_profiles_updated  before update on public.profiles      for each row execute function public.tg_set_updated_at();
create trigger trg_packages_updated  before update on public.packages      for each row execute function public.tg_set_updated_at();
create trigger trg_employees_updated before update on public.employees     for each row execute function public.tg_set_updated_at();
create trigger trg_customers_updated before update on public.customers     for each row execute function public.tg_set_updated_at();
create trigger trg_templates_updated before update on public.sms_templates for each row execute function public.tg_set_updated_at();

-- ------------------------------------------------------------
-- Stamp "created_by" with the logged-in user. Browser sessions cannot
-- spoof it; SQL imports may supply their own value (or leave it null).
-- ------------------------------------------------------------
create or replace function public.tg_stamp_creator()
returns trigger language plpgsql as $$
begin
  if auth.role() = 'authenticated' or new.created_by is null then
    new.created_by := coalesce(auth.uid(), new.created_by);
  end if;
  return new;
end $$;

create trigger trg_complaints_stamp before insert on public.complaints          for each row execute function public.tg_stamp_creator();
create trigger trg_journal_stamp    before insert on public.journal_entries     for each row execute function public.tg_stamp_creator();
create trigger trg_acctx_stamp      before insert on public.account_transactions for each row execute function public.tg_stamp_creator();
create trigger trg_fees_stamp       before insert on public.monthly_fees        for each row execute function public.tg_stamp_creator();

-- ------------------------------------------------------------
-- Customer balance = opening_balance + everything still unpaid.
-- Always recomputed from the base tables, so it cannot drift.
-- ------------------------------------------------------------
create or replace function public.recompute_customer_balance(p_customer_id bigint)
returns void language plpgsql security definer set search_path = public
as $$
begin
  update public.customers c
  set balance = c.opening_balance + coalesce((
    select sum(greatest(f.amount_due - coalesce(pp.paid, 0), 0))
    from public.monthly_fees f
    left join lateral (
      select sum(p.amount_paid) as paid
      from public.payments p
      where p.monthly_fee_id = f.id and p.reversed_at is null
    ) pp on true
    where f.customer_id = c.id
  ), 0)
  where c.id = p_customer_id;
end $$;

create or replace function public.recompute_all_balances()
returns integer language plpgsql security definer set search_path = public
as $$
declare r record; n integer := 0;
begin
  if not (public.is_trusted_caller() or public.is_admin()) then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  for r in select id from public.customers loop
    perform public.recompute_customer_balance(r.id); n := n + 1;
  end loop;
  return n;
end $$;

-- ------------------------------------------------------------
-- CUSTOMERS
-- ------------------------------------------------------------
create sequence if not exists public.customer_code_seq;

create or replace function public.tg_customers_prepare()
returns trigger language plpgsql security definer set search_path = public
as $$
declare v_phone text; v_code text;
begin
  new.username := btrim(new.username);

  if tg_op = 'INSERT' or new.phone is distinct from old.phone then
    v_phone := public.normalize_phone(new.phone);
    if v_phone is null then
      raise exception 'Invalid phone number "%". Enter 7-15 digits, e.g. 0300 1234567.', new.phone using errcode = '22023';
    end if;
    new.phone := v_phone;
  end if;

  if tg_op = 'INSERT' then
    -- Staff (browser, non-admin) cannot start a customer with money owing or a custom status.
    if auth.role() = 'authenticated' and not public.is_admin() then
      new.opening_balance := 0;
      new.service_status  := 'on';
      new.customer_status := 'active';
    end if;

    -- Generate a code that is guaranteed unused (safe after imports with their own codes).
    if new.customer_code is null or btrim(new.customer_code) = '' then
      loop
        v_code := 'CUS-' || lpad(nextval('public.customer_code_seq')::text, 5, '0');
        exit when not exists (select 1 from public.customers where customer_code = v_code);
      end loop;
      new.customer_code := v_code;
    else
      new.customer_code := btrim(new.customer_code);
    end if;

    new.created_by := coalesce(case when auth.role() = 'authenticated' then auth.uid() end, new.created_by, auth.uid());
    new.balance := new.opening_balance;       -- the fee triggers will add unpaid fees
  else
    new.customer_code := old.customer_code;   -- immutable
    new.created_by    := old.created_by;      -- immutable
    if new.opening_balance is distinct from old.opening_balance then
      new.balance := old.balance - old.opening_balance + new.opening_balance;
    end if;
  end if;
  return new;
end $$;

create trigger trg_customers_prepare before insert or update on public.customers
  for each row execute function public.tg_customers_prepare();

-- Staff may not touch money / status / plan columns, even via the raw API.
create or replace function public.tg_customers_protect_columns()
returns trigger language plpgsql as $$
begin
  if public.is_trusted_session() or public.is_admin() then return new; end if;
  if new.balance          is distinct from old.balance
     or new.opening_balance is distinct from old.opening_balance
     or new.service_status  is distinct from old.service_status
     or new.customer_status is distinct from old.customer_status
     or new.package_id      is distinct from old.package_id
     or new.area_id         is distinct from old.area_id
     or new.join_date       is distinct from old.join_date
  then
    raise exception 'Staff cannot change balance, opening balance, service status, customer status, package, area or join date'
      using errcode = '42501';
  end if;
  return new;
end $$;

create trigger trg_customers_protect before update on public.customers
  for each row execute function public.tg_customers_protect_columns();

-- A new (or re-activated) customer gets this month's fee straight away,
-- so they show up on the Collections page without waiting for a refresh.
create or replace function public.tg_customers_first_fee()
returns trigger language plpgsql security definer set search_path = public
as $$
begin
  if public.is_bulk_load() or new.customer_status <> 'active' then return null; end if;
  if tg_op = 'UPDATE' and old.customer_status = 'active' then return null; end if;
  insert into public.monthly_fees (customer_id, billing_month, package_id)
  values (new.id, date_trunc('month', public.today_pk()::timestamp)::date, new.package_id)
  on conflict (customer_id, billing_month) do nothing;
  return null;
end $$;

create trigger trg_customers_first_fee after insert or update of customer_status on public.customers
  for each row execute function public.tg_customers_first_fee();

-- ------------------------------------------------------------
-- EMPLOYEES
-- ------------------------------------------------------------
create or replace function public.tg_employees_prepare()
returns trigger language plpgsql as $$
begin
  new.full_name := btrim(new.full_name);
  if new.phone is not null and btrim(new.phone) <> '' then
    new.phone := public.normalize_phone(new.phone);
    if new.phone is null then
      raise exception 'Invalid phone number.' using errcode = '22023';
    end if;
  else
    new.phone := null;
  end if;
  return new;
end $$;

create trigger trg_employees_prepare before insert or update on public.employees
  for each row execute function public.tg_employees_prepare();

-- An admin cannot lock themselves out.
create or replace function public.tg_profiles_guard()
returns trigger language plpgsql as $$
begin
  if public.is_trusted_session() then return new; end if;
  if auth.uid() = old.id and (new.role is distinct from old.role or new.is_active is distinct from old.is_active) then
    raise exception 'You cannot change your own role or active status' using errcode = '42501';
  end if;
  return new;
end $$;

create trigger trg_profiles_guard before update on public.profiles
  for each row execute function public.tg_profiles_guard();

-- ------------------------------------------------------------
-- MONTHLY FEES - fill defaults so a plain insert just works
-- ------------------------------------------------------------
create or replace function public.tg_fees_prepare()
returns trigger language plpgsql security definer set search_path = public
as $$
declare v_pkg bigint;
begin
  new.billing_month := date_trunc('month', new.billing_month::timestamp)::date;

  if new.package_id is null then
    select package_id into new.package_id from public.customers where id = new.customer_id;
  end if;
  if new.amount_due is null then
    select monthly_fee into new.amount_due from public.packages where id = new.package_id;
  end if;
  if new.amount_due is null then
    raise exception 'Cannot work out the fee amount: give amount_due or a package' using errcode = '22023';
  end if;
  if new.due_date is null then
    new.due_date := new.billing_month + 9;     -- the 10th
  end if;
  return new;
end $$;

create trigger trg_fees_prepare before insert on public.monthly_fees
  for each row execute function public.tg_fees_prepare();

create or replace function public.tg_fees_after()
returns trigger language plpgsql security definer set search_path = public
as $$
begin
  if tg_op = 'DELETE' then
    perform public.recompute_customer_balance(old.customer_id);
  else
    perform public.recompute_customer_balance(new.customer_id);
  end if;
  return null;
end $$;

create trigger trg_fees_after after insert or update or delete on public.monthly_fees
  for each row execute function public.tg_fees_after();

-- ------------------------------------------------------------
-- RECEIPT NUMBERS: RCP-YYYY-NNNNNN. An advisory lock serialises
-- concurrent payments so two cannot get the same number.
-- ------------------------------------------------------------
create or replace function public.generate_receipt_number()
returns text language plpgsql security definer set search_path = public
as $$
declare v_year text := to_char(public.today_pk(), 'YYYY'); v_next bigint; v_rcp text;
begin
  perform pg_advisory_xact_lock(hashtext('icrms.receipt_number'));
  select coalesce(max(substr(receipt_number, 10)::bigint), 0) + 1 into v_next
  from public.payments
  where receipt_number ~ ('^RCP-' || v_year || '-[0-9]+$');
  loop
    v_rcp := 'RCP-' || v_year || '-' || lpad(v_next::text, 6, '0');
    exit when not exists (select 1 from public.payments where receipt_number = v_rcp);
    v_next := v_next + 1;
  end loop;
  return v_rcp;
end $$;

-- ------------------------------------------------------------
-- PAYMENTS - one place enforces every money rule, for any insert path
-- ------------------------------------------------------------
create or replace function public.tg_payments_prepare()
returns trigger language plpgsql security definer set search_path = public
as $$
declare v_fee_customer bigint; v_due numeric; v_paid numeric;
begin
  -- Lock the fee so two simultaneous payments cannot overpay it.
  select customer_id, amount_due into v_fee_customer, v_due
  from public.monthly_fees where id = new.monthly_fee_id for update;
  if not found then
    raise exception 'Monthly fee % does not exist', new.monthly_fee_id using errcode = 'P0002';
  end if;

  if new.customer_id is null then
    new.customer_id := v_fee_customer;
  elsif new.customer_id <> v_fee_customer then
    raise exception 'This fee belongs to a different customer' using errcode = '22023';
  end if;

  if new.reversed_at is null then
    select coalesce(sum(amount_paid), 0) into v_paid
    from public.payments where monthly_fee_id = new.monthly_fee_id and reversed_at is null;
    if v_due - v_paid <= 0 then
      raise exception 'This fee is already fully paid' using errcode = '22023';
    end if;
    if new.amount_paid > v_due - v_paid then
      raise exception 'Payment exceeds the remaining balance (Rs. %)', (v_due - v_paid) using errcode = '22023';
    end if;
  end if;

  if auth.role() = 'authenticated' then
    new.received_by := auth.uid();
  elsif new.received_by is null then
    new.received_by := auth.uid();
  end if;

  if new.receipt_number is null or btrim(new.receipt_number) = '' then
    new.receipt_number := public.generate_receipt_number();
  end if;
  new.notes := nullif(btrim(new.notes), '');
  return new;
end $$;

create trigger trg_payments_prepare before insert on public.payments
  for each row execute function public.tg_payments_prepare();

-- After a payment: refresh the balance, post the cash book + account entry,
-- and post the opposite entries when it is reversed.
create or replace function public.tg_payments_after()
returns trigger language plpgsql security definer set search_path = public
as $$
declare v_account bigint; v_name text; v_type text;
begin
  perform public.recompute_customer_balance(new.customer_id);
  if public.is_bulk_load() then return null; end if;

  if tg_op = 'INSERT' and new.reversed_at is null then
    select username into v_name from public.customers where id = new.customer_id;
    insert into public.journal_entries (entry_date, entry_type, category, amount, description, reference_payment_id, created_by)
    values (new.payment_date, 'income', 'Fee collection', new.amount_paid,
            'Receipt ' || new.receipt_number || ' - ' || coalesce(v_name, ''), new.id, new.received_by);

    v_type := case when new.payment_method = 'bank_transfer' then 'bank' else 'cash' end;
    select id into v_account from public.accounts where is_active and account_type = v_type order by id limit 1;
    if v_account is not null then
      insert into public.account_transactions (account_id, transaction_type, amount, description, reference_payment_id, created_by)
      values (v_account, 'credit', new.amount_paid, 'Receipt ' || new.receipt_number, new.id, new.received_by);
    end if;

  elsif tg_op = 'UPDATE' and old.reversed_at is null and new.reversed_at is not null then
    insert into public.journal_entries (entry_date, entry_type, category, amount, description, reference_payment_id, created_by)
    values (public.today_pk(), 'expense', 'Payment reversal', new.amount_paid,
            'Reversed receipt ' || new.receipt_number || ': ' || coalesce(new.reversal_reason, ''), new.id, new.reversed_by);

    select account_id into v_account from public.account_transactions
    where reference_payment_id = new.id and transaction_type = 'credit' order by id limit 1;
    if v_account is not null then
      insert into public.account_transactions (account_id, transaction_type, amount, description, reference_payment_id, created_by)
      values (v_account, 'debit', new.amount_paid, 'Reversal of ' || new.receipt_number, new.id, new.reversed_by);
    end if;
  end if;
  return null;
end $$;

create trigger trg_payments_after after insert or update on public.payments
  for each row execute function public.tg_payments_after();

-- ------------------------------------------------------------
-- ACCOUNT balances follow transactions (credit +, debit -)
-- ------------------------------------------------------------
create or replace function public.tg_account_tx_apply()
returns trigger language plpgsql security definer set search_path = public
as $$
begin
  if public.is_bulk_load() then return null; end if;
  update public.accounts
  set current_balance = current_balance + case when new.transaction_type = 'credit' then new.amount else -new.amount end
  where id = new.account_id;
  return null;
end $$;

create trigger trg_account_tx_apply after insert on public.account_transactions
  for each row execute function public.tg_account_tx_apply();

-- ------------------------------------------------------------
-- COMPLAINTS: resolved_at follows status; staff can only work a complaint
-- ------------------------------------------------------------
create or replace function public.tg_complaints_prepare()
returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE' and not (public.is_trusted_session() or public.is_admin()) then
    if new.customer_id    is distinct from old.customer_id
       or new.complaint_text is distinct from old.complaint_text
       or new.category       is distinct from old.category
       or new.assigned_to    is distinct from old.assigned_to
       or new.created_by     is distinct from old.created_by
    then
      raise exception 'Staff can only change the status and resolution notes of a complaint' using errcode = '42501';
    end if;
  end if;

  if new.status in ('resolved','closed') then
    new.resolved_at := coalesce(new.resolved_at, now());
  else
    new.resolved_at := null;
  end if;
  return new;
end $$;

create trigger trg_complaints_prepare before insert or update on public.complaints
  for each row execute function public.tg_complaints_prepare();

-- ------------------------------------------------------------
-- Financial records cannot be deleted
-- ------------------------------------------------------------
create or replace function public.tg_block_delete()
returns trigger language plpgsql as $$
begin
  raise exception 'Rows in % cannot be deleted. Reverse or deactivate instead.', tg_table_name using errcode = '42501';
end $$;

create trigger trg_payments_no_delete before delete on public.payments             for each row execute function public.tg_block_delete();
create trigger trg_fees_no_delete     before delete on public.monthly_fees         for each row execute function public.tg_block_delete();
create trigger trg_journal_no_delete  before delete on public.journal_entries      for each row execute function public.tg_block_delete();
create trigger trg_acctx_no_delete    before delete on public.account_transactions for each row execute function public.tg_block_delete();
create trigger trg_audit_no_delete    before delete on public.company_logs         for each row execute function public.tg_block_delete();

-- ------------------------------------------------------------
-- Audit trail. It must NEVER be the reason a real insert fails,
-- so any problem here is downgraded to a warning.
-- ------------------------------------------------------------
create or replace function public.tg_audit()
returns trigger language plpgsql security definer set search_path = public
as $$
declare v_row jsonb; v_details jsonb;
begin
  if public.is_bulk_load() then return null; end if;
  begin
    v_row := to_jsonb(case when tg_op = 'DELETE' then old else new end);
    v_details := case when tg_op = 'UPDATE'
                      then jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new))
                      else v_row end;
    insert into public.company_logs (actor_id, action, entity_type, entity_id, details)
    values (case when exists (select 1 from public.profiles where id = auth.uid()) then auth.uid() end,
            tg_table_name || '.' || lower(tg_op), tg_table_name, v_row ->> 'id', v_details);
  exception when others then
    raise warning 'audit log skipped: %', sqlerrm;
  end;
  return null;
end $$;

create trigger trg_audit_customers_ins after insert on public.customers for each row execute function public.tg_audit();
create trigger trg_audit_customers_upd after update on public.customers for each row
  when ((to_jsonb(new) - 'balance' - 'updated_at') is distinct from (to_jsonb(old) - 'balance' - 'updated_at'))
  execute function public.tg_audit();
create trigger trg_audit_payments   after insert or update on public.payments      for each row execute function public.tg_audit();
create trigger trg_audit_profiles   after insert or update on public.profiles      for each row execute function public.tg_audit();
create trigger trg_audit_employees  after insert or update on public.employees     for each row execute function public.tg_audit();
create trigger trg_audit_packages   after insert or update on public.packages      for each row execute function public.tg_audit();
create trigger trg_audit_areas      after insert or update or delete on public.areas for each row execute function public.tg_audit();
create trigger trg_audit_complaints after insert or update on public.complaints    for each row execute function public.tg_audit();
create trigger trg_audit_templates  after insert or update on public.sms_templates for each row execute function public.tg_audit();
create trigger trg_audit_journal    after insert on public.journal_entries          for each row execute function public.tg_audit();
create trigger trg_audit_accounts   after insert or update on public.accounts       for each row execute function public.tg_audit();

-- >>>>>>>> migrations/20261015000003_api.sql
-- ============================================================
-- 20261015000003 - API: views + RPC functions used by the app
-- ============================================================
-- Views run with the owner's rights on purpose (so a staff member sees
-- correct paid/remaining totals although RLS only lets them read their
-- own payments). Each view therefore filters on is_active_user() itself;
-- the SQL editor / service role (trusted session) can read them too.
-- ============================================================

-- Per-fee paid / remaining / status. Reversed payments are ignored.
-- Status precedence: paid > overdue > partial > unpaid.
create or replace view public.fee_balances as
select
  mf.id                                   as monthly_fee_id,
  mf.customer_id,
  mf.billing_month,
  mf.amount_due,
  mf.due_date,
  coalesce(sum(p.amount_paid) filter (where p.reversed_at is null), 0)::numeric(12,2) as total_paid,
  (mf.amount_due - coalesce(sum(p.amount_paid) filter (where p.reversed_at is null), 0))::numeric(12,2) as remaining,
  case
    when mf.amount_due - coalesce(sum(p.amount_paid) filter (where p.reversed_at is null), 0) <= 0 then 'paid'
    when mf.due_date < public.today_pk() then 'overdue'
    when coalesce(sum(p.amount_paid) filter (where p.reversed_at is null), 0) > 0 then 'partial'
    else 'unpaid'
  end                                     as status
from public.monthly_fees mf
left join public.payments p on p.monthly_fee_id = mf.id
where public.is_active_user() or public.is_trusted_session()
group by mf.id, mf.customer_id, mf.billing_month, mf.amount_due, mf.due_date;

-- One row per active customer with the current month's fee (Collections page).
create or replace view public.customer_fee_status as
select
  c.id as customer_id, c.customer_code, c.username, c.phone, c.area_id, c.package_id,
  c.customer_status, c.service_status, c.balance,
  fb.monthly_fee_id, fb.billing_month, fb.amount_due,
  coalesce(fb.total_paid, 0)::numeric(12,2) as total_paid,
  coalesce(fb.remaining, 0)::numeric(12,2)  as remaining,
  fb.status
from public.customers c
left join public.fee_balances fb
  on fb.customer_id = c.id
 and fb.billing_month = date_trunc('month', public.today_pk()::timestamp)::date
where c.customer_status = 'active'
  and (public.is_active_user() or public.is_trusted_session());

-- Total outstanding per customer (opening balance + unpaid fees).
create or replace view public.customer_balances as
select
  c.id as customer_id, c.customer_code, c.username, c.phone, c.area_id, c.opening_balance,
  coalesce(sum(fb.remaining) filter (where fb.remaining > 0), 0)::numeric(12,2) as unpaid_invoices,
  (c.opening_balance + coalesce(sum(fb.remaining) filter (where fb.remaining > 0), 0))::numeric(12,2) as total_outstanding
from public.customers c
left join public.fee_balances fb on fb.customer_id = c.id
where public.is_active_user() or public.is_trusted_session()
group by c.id, c.customer_code, c.username, c.phone, c.area_id, c.opening_balance;

-- Salary-free employee list for dropdowns.
create or replace view public.employee_directory as
select e.id, e.full_name, e.area_id, e.is_active, e.profile_id, e.role_title, e.joined_at
from public.employees e
where public.is_active_user() or public.is_trusted_session();

-- ------------------------------------------------------------
-- ensure_monthly_fees(month): one fee per active customer. Idempotent.
-- Customers are only billed from their join month onward.
-- ------------------------------------------------------------
create or replace function public.ensure_monthly_fees(p_month date)
returns integer language plpgsql security definer set search_path = public
as $$
declare
  v_month date := date_trunc('month', p_month::timestamp)::date;
  v_end   date := (date_trunc('month', p_month::timestamp) + interval '1 month - 1 day')::date;
  v_count integer;
begin
  if not (public.is_active_user() or public.is_trusted_caller()) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if v_month > date_trunc('month', public.today_pk()::timestamp)::date then
    raise exception 'Cannot create fees for a future month' using errcode = '22023';
  end if;

  insert into public.monthly_fees (customer_id, billing_month, package_id)
  select c.id, v_month, c.package_id
  from public.customers c
  where c.customer_status = 'active' and c.join_date <= v_end
  on conflict (customer_id, billing_month) do nothing;

  get diagnostics v_count = row_count;
  return v_count;
end $$;

-- ------------------------------------------------------------
-- record_payment - used by the Collections screen.
-- The money rules live in the payments trigger; this adds the
-- WhatsApp message log and returns what the screen needs.
-- ------------------------------------------------------------
create or replace function public.record_payment(
  p_customer_id    bigint,
  p_monthly_fee_id bigint,
  p_amount         numeric,
  p_method         text,
  p_notes          text default null
)
returns jsonb language plpgsql security definer set search_path = public
as $$
declare
  v_fee      record;
  v_customer record;
  v_pay      record;
  v_after    numeric;
  v_template text;
  v_message  text;
  v_sms_id   bigint;
begin
  if not public.is_active_user() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be greater than zero' using errcode = '22023';
  end if;
  if p_method is null or p_method not in ('cash','bank_transfer','other') then
    raise exception 'Invalid payment method' using errcode = '22023';
  end if;

  select * into v_fee from public.monthly_fees where id = p_monthly_fee_id and customer_id = p_customer_id;
  if not found then
    raise exception 'Monthly fee not found for this customer' using errcode = 'P0002';
  end if;

  insert into public.payments (customer_id, monthly_fee_id, amount_paid, payment_method, notes)
  values (p_customer_id, p_monthly_fee_id, p_amount, p_method, p_notes)
  returning id, receipt_number into v_pay;

  select id, username, phone, balance into v_customer from public.customers where id = p_customer_id;

  select v_fee.amount_due - coalesce(sum(amount_paid), 0) into v_after
  from public.payments where monthly_fee_id = p_monthly_fee_id and reversed_at is null;

  select template_text into v_template
  from public.sms_templates where lower(name) = 'payment received' and is_active limit 1;

  if v_template is not null then
    v_message := v_template;
    v_message := replace(v_message, '{{customer_name}}',  v_customer.username);
    v_message := replace(v_message, '{{amount}}',         to_char(p_amount, 'FM999999990.00'));
    v_message := replace(v_message, '{{month}}',          to_char(v_fee.billing_month, 'FMMonth YYYY'));
    v_message := replace(v_message, '{{remaining}}',      to_char(v_after, 'FM999999990.00'));
    v_message := replace(v_message, '{{balance}}',        to_char(v_customer.balance, 'FM999999990.00'));
    v_message := replace(v_message, '{{receipt_number}}', v_pay.receipt_number);
    v_message := replace(v_message, '{{company_name}}',   public.company_name());

    insert into public.sms_logs (customer_id, phone, message_text, status, provider, sent_by, related_payment_id)
    values (p_customer_id, v_customer.phone, v_message, 'pending', 'whatsapp_manual', auth.uid(), v_pay.id)
    returning id into v_sms_id;
  end if;

  return jsonb_build_object(
    'payment_id', v_pay.id, 'receipt_number', v_pay.receipt_number,
    'sms_log_id', v_sms_id, 'message', v_message, 'phone', v_customer.phone);
end $$;

-- reverse_payment - admin only. The trigger posts the opposite journal / account entries.
create or replace function public.reverse_payment(p_payment_id bigint, p_reason text)
returns void language plpgsql security definer set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Only an admin can reverse a payment' using errcode = '42501';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'A reversal reason is required' using errcode = '22023';
  end if;

  update public.payments
  set reversed_at = now(), reversed_by = auth.uid(), reversal_reason = btrim(p_reason)
  where id = p_payment_id and reversed_at is null;

  if not found then
    raise exception 'Payment not found or already reversed' using errcode = 'P0002';
  end if;
end $$;

-- mark_whatsapp_sent - staff confirm a message went out.
create or replace function public.mark_whatsapp_sent(p_sms_log_id bigint)
returns void language plpgsql security definer set search_path = public
as $$
declare v_payment_id bigint;
begin
  if not public.is_active_user() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  update public.sms_logs set status = 'sent', sent_at = now()
  where id = p_sms_log_id and (sent_by = auth.uid() or public.is_admin())
  returning related_payment_id into v_payment_id;

  if not found then
    raise exception 'Message not found' using errcode = 'P0002';
  end if;

  update public.payments set whatsapp_sent = true, whatsapp_sent_at = now() where id = v_payment_id;
end $$;

-- ------------------------------------------------------------
-- Dashboards (one round trip each)
-- ------------------------------------------------------------
create or replace function public.admin_dashboard_stats()
returns jsonb language plpgsql stable security definer set search_path = public
as $$
declare v_month date := date_trunc('month', public.today_pk()::timestamp)::date;
begin
  if not public.is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'total_customers',    (select count(*) from public.customers),
    'active_customers',   (select count(*) from public.customers where customer_status = 'active'),
    'inactive_customers', (select count(*) from public.customers where customer_status = 'inactive'),
    'month_collections',  coalesce((select sum(amount_paid) from public.payments
                                    where reversed_at is null and payment_date >= v_month), 0),
    'outstanding_total',  coalesce((select sum(balance) from public.customers where balance > 0), 0),
    'unpaid_count',       (select count(*) from public.fee_balances where billing_month = v_month and status = 'unpaid'),
    'partial_count',      (select count(*) from public.fee_balances where billing_month = v_month and status = 'partial'),
    'overdue_count',      (select count(*) from public.fee_balances where billing_month = v_month and status = 'overdue'),
    'recent_payments',    coalesce((
      select jsonb_agg(x) from (
        select p.id, p.amount_paid, p.payment_date, p.receipt_number, c.username as customer_name
        from public.payments p join public.customers c on c.id = p.customer_id
        where p.reversed_at is null order by p.created_at desc, p.id desc limit 5) x), '[]'::jsonb),
    'recent_customers',   coalesce((
      select jsonb_agg(x) from (
        select id, customer_code, username, created_at
        from public.customers order by created_at desc, id desc limit 5) x), '[]'::jsonb),
    'customers_per_area', coalesce((
      select jsonb_agg(x) from (
        select a.name as name, count(c.id) as count
        from public.areas a left join public.customers c on c.area_id = a.id
        group by a.id, a.name order by a.name) x), '[]'::jsonb),
    'collections_per_employee', coalesce((
      select jsonb_agg(x) from (
        select pr.full_name as name, sum(p.amount_paid) as total
        from public.payments p join public.profiles pr on pr.id = p.received_by
        where p.reversed_at is null and p.payment_date >= v_month
        group by pr.id, pr.full_name order by total desc) x), '[]'::jsonb)
  );
end $$;

create or replace function public.staff_dashboard_stats()
returns jsonb language plpgsql stable security definer set search_path = public
as $$
declare
  v_today date := public.today_pk();
  v_month date := date_trunc('month', public.today_pk()::timestamp)::date;
  v_emp_id bigint; v_area_id bigint; v_area_name text;
begin
  if not public.is_active_user() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  select e.id, e.area_id, a.name into v_emp_id, v_area_id, v_area_name
  from public.employees e left join public.areas a on a.id = e.area_id
  where e.profile_id = auth.uid();

  return jsonb_build_object(
    'today_collections', coalesce((select sum(amount_paid) from public.payments
                                   where received_by = auth.uid() and reversed_at is null and payment_date = v_today), 0),
    'month_collections', coalesce((select sum(amount_paid) from public.payments
                                   where received_by = auth.uid() and reversed_at is null and payment_date >= v_month), 0),
    'my_customers',      (select count(*) from public.customers where seller_id = v_emp_id),
    'area_outstanding',  coalesce((select sum(balance) from public.customers
                                   where area_id = v_area_id and balance > 0), 0),
    'area_name',         v_area_name
  );
end $$;

-- ------------------------------------------------------------
-- Maintenance helpers (admin / SQL editor)
-- ------------------------------------------------------------
-- After importing rows that carry their own ids, move every id counter
-- past the highest existing id so new rows never collide.
create or replace function public.fix_sequences()
returns text language plpgsql security definer set search_path = public
as $$
declare r record; v_max bigint; v_n integer := 0;
begin
  if not (public.is_trusted_caller() or public.is_admin()) then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  for r in
    select c.table_name, c.column_name, pg_get_serial_sequence('public.' || quote_ident(c.table_name), c.column_name) as seq
    from information_schema.columns c
    join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name and t.table_type = 'BASE TABLE'
    where c.table_schema = 'public' and c.is_identity = 'YES'
  loop
    continue when r.seq is null;
    execute format('select coalesce(max(%I), 0) from public.%I', r.column_name, r.table_name) into v_max;
    perform setval(r.seq, greatest(v_max, 1), v_max > 0);
    v_n := v_n + 1;
  end loop;

  select coalesce(max(nullif(regexp_replace(customer_code, '\D', '', 'g'), '')::bigint), 0) into v_max from public.customers;
  perform setval('public.customer_code_seq', greatest(v_max, 1), v_max > 0);
  return v_n || ' id sequences and the customer code sequence were synchronised';
end $$;

-- Cheap ping that keeps a free-tier project awake.
create or replace function public.health_check()
returns jsonb language sql stable
as $$ select jsonb_build_object('ok', true) $$;

-- >>>>>>>> migrations/20261015000004_security.sql
-- ============================================================
-- 20261015000004 - SECURITY: grants + row level security
-- ============================================================
--   admin : everything except deleting financial records
--   staff : customers, complaints they handle, their own payments
--   anon  : nothing (only health_check())
-- Money tables (monthly_fees, payments, sms_logs, company_logs) have no
-- browser write access: they change only through triggers and RPCs.
-- Safe to re-run.
-- ============================================================

alter table public.profiles             enable row level security;
alter table public.areas                enable row level security;
alter table public.packages             enable row level security;
alter table public.employees            enable row level security;
alter table public.customers            enable row level security;
alter table public.monthly_fees         enable row level security;
alter table public.payments             enable row level security;
alter table public.complaints           enable row level security;
alter table public.journal_entries      enable row level security;
alter table public.accounts             enable row level security;
alter table public.account_transactions enable row level security;
alter table public.sms_templates        enable row level security;
alter table public.sms_logs             enable row level security;
alter table public.company_logs         enable row level security;

-- Table privileges (RLS then narrows them per row)
revoke all on all tables    in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
alter default privileges in schema public revoke all on tables    from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;

grant select on all tables in schema public to authenticated;     -- tables + views

grant update                 on public.profiles             to authenticated;
grant insert, update, delete on public.areas                to authenticated;
grant insert, update         on public.packages             to authenticated;
grant insert, update         on public.employees            to authenticated;
grant insert, update         on public.customers            to authenticated;
grant insert, update         on public.complaints           to authenticated;
grant insert                 on public.journal_entries      to authenticated;
grant insert                 on public.accounts             to authenticated;
grant update (name, is_active) on public.accounts           to authenticated;
grant insert                 on public.account_transactions to authenticated;
grant insert, update         on public.sms_templates        to authenticated;

-- Function privileges: remove the default "everyone", grant what is needed.
revoke all on all functions in schema public from public, anon;
grant execute on function public.is_admin(), public.is_active_user(), public.is_trusted_session(),
                          public.is_bulk_load(), public.is_trusted_caller(), public.today_pk(), public.company_name(),
                          public.normalize_phone(text)                          to authenticated;
grant execute on function public.ensure_monthly_fees(date),
                          public.record_payment(bigint, bigint, numeric, text, text),
                          public.reverse_payment(bigint, text),
                          public.mark_whatsapp_sent(bigint),
                          public.admin_dashboard_stats(),
                          public.staff_dashboard_stats(),
                          public.fix_sequences(),
                          public.recompute_all_balances()                       to authenticated;
grant execute on function public.health_check()                                 to anon, authenticated;

-- ---------------- policies ----------------
-- profiles: your own row, or everything for an admin
create policy profiles_select on public.profiles for select to authenticated
  using (id = (select auth.uid()) or public.is_admin());
create policy profiles_update on public.profiles for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- areas / packages: any active user reads, admin writes
create policy areas_select on public.areas for select to authenticated using (public.is_active_user());
create policy areas_write  on public.areas for all    to authenticated using (public.is_admin()) with check (public.is_admin());
create policy packages_select on public.packages for select to authenticated using (public.is_active_user());
create policy packages_write  on public.packages for all    to authenticated using (public.is_admin()) with check (public.is_admin());

-- employees: admin sees all (salary!); staff see only their own row
create policy employees_select on public.employees for select to authenticated
  using (public.is_admin() or (profile_id = (select auth.uid()) and public.is_active_user()));
create policy employees_insert on public.employees for insert to authenticated with check (public.is_admin());
create policy employees_update on public.employees for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- customers: any active user (column limits are enforced by triggers)
create policy customers_select on public.customers for select to authenticated using (public.is_active_user());
create policy customers_insert on public.customers for insert to authenticated with check (public.is_active_user());
create policy customers_update on public.customers for update to authenticated
  using (public.is_active_user()) with check (public.is_active_user());

-- monthly_fees: read only
create policy fees_select on public.monthly_fees for select to authenticated using (public.is_active_user());

-- payments: admin sees all; staff see what they collected
create policy payments_select on public.payments for select to authenticated
  using (public.is_active_user() and (public.is_admin() or received_by = (select auth.uid())));

-- complaints: admin all; staff the ones they created or are assigned to
create policy complaints_select on public.complaints for select to authenticated
  using (public.is_active_user() and (public.is_admin()
         or created_by = (select auth.uid()) or assigned_to = (select auth.uid())));
create policy complaints_insert on public.complaints for insert to authenticated
  with check (public.is_active_user());                       -- created_by is stamped by trigger
create policy complaints_update on public.complaints for update to authenticated
  using (public.is_active_user() and (public.is_admin() or assigned_to = (select auth.uid()) or created_by = (select auth.uid())))
  with check (public.is_active_user() and (public.is_admin() or assigned_to = (select auth.uid()) or created_by = (select auth.uid())));

-- journal / accounts: admin only
create policy journal_select  on public.journal_entries      for select to authenticated using (public.is_admin());
create policy journal_insert  on public.journal_entries      for insert to authenticated with check (public.is_admin());
create policy accounts_select on public.accounts             for select to authenticated using (public.is_admin());
create policy accounts_insert on public.accounts             for insert to authenticated with check (public.is_admin() and current_balance = 0);
create policy accounts_update on public.accounts             for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy acctx_select    on public.account_transactions for select to authenticated using (public.is_admin());
create policy acctx_insert    on public.account_transactions for insert to authenticated with check (public.is_admin());

-- sms templates: admin only (record_payment reads them as definer)
create policy templates_select on public.sms_templates for select to authenticated using (public.is_admin());
create policy templates_write  on public.sms_templates for all    to authenticated using (public.is_admin()) with check (public.is_admin());

-- sms logs: admin all; staff their own. Writes: functions only
create policy sms_logs_select on public.sms_logs for select to authenticated
  using (public.is_active_user() and (public.is_admin() or sent_by = (select auth.uid())));

-- audit log: admin read-only
create policy logs_select on public.company_logs for select to authenticated using (public.is_admin());

-- Make PostgREST pick up the new objects immediately.
notify pgrst, 'reload schema';

